//! Shared support for the rendering_writer differential tests.
//!
//! Loads `tests/write_corpus.json` (generated by
//! `differential/gen_write_corpus.py`, which runs the REAL production pikepdf
//! strip pipeline) into serde DTOs and measures the same semantic facts on the
//! mupdf-rs side: per-page word count (fitz vs mupdf-rs extraction paths differ
//! up to ~5%, so 10% relative tolerance) and ink ratio (both wrap the same
//! MuPDF C renderer, so ±0.02 absolute).

#![allow(dead_code)]

use std::collections::HashMap;
use std::sync::OnceLock;

use base64::Engine;
use mupdf::{Document, TextExtractOptions, TextPageFlags};
use rendering_core::source_cleanup::hit_test::RectTuple;
use rendering_reader::render::render_page_clip_gray;
use serde::Deserialize;

/// Relative word-count tolerance vs fitz `get_text("words")` (different
/// extraction path — see rendering_reader's reader.rs).
pub const WORD_COUNT_TOLERANCE: f64 = 0.10;
/// Absolute ink-ratio tolerance. Both engines wrap MuPDF; the write path only
/// needs semantic equivalence.
pub const INK_RATIO_TOLERANCE: f64 = 0.02;

// --- corpus loading ----------------------------------------------------------

