fn load_corpus() -> &'static WriteCorpus {
    static CORPUS: OnceLock<WriteCorpus> = OnceLock::new();
    CORPUS.get_or_init(|| {
        let raw = include_str!("../write_corpus.json");
        serde_json::from_str(raw).expect("failed to parse write_corpus.json")
    })
}

pub fn corpus() -> &'static WriteCorpus {
    load_corpus()
}

